/**
 * Types for `humanoid.rig.json`. The rig is DATA (VISION §5.2: "the rig must be data-driven"),
 * so the viewer, the limit clamp, the IK solver, the exporters and the MCP `get_rig` tool all read
 * this one shape. It is generated by `tools/gen-rig.py`; the generator is authoritative for the
 * *content*, this file is authoritative for the *contract*.
 */
export type Vec3 = readonly [number, number, number];
export type AxisName = "flex" | "side" | "twist";

/** One degree of freedom: rotation about a unit vector, positive == the anatomically positive motion. */
export interface JointAxis {
  readonly name: AxisName;
  /** Unit vector in the joint's rest frame, which equals the world frame (identity rest rotation). */
  readonly axis: Vec3;
  readonly min: number;
  readonly max: number;
  /**
   * Non-negative allowances in degrees: [past min, past max]. The solver may settle inside
   * `min - graze[0] .. max + graze[1]` without being reported; past that it clamps and records an
   * `adjusted` entry. Exported keyframes are always clamped to min..max, so an engine never sees an
   * illegal value even though IK was allowed to graze (VISION §6's "clamp and report").
   */
  readonly graze: readonly [number, number];
  /** Written for the AI: the sentence `get_rig` returns verbatim. */
  readonly positiveMeans: string;
}

export interface RigJoint {
  readonly name: string;
  /** Semantic key for matching other rigs; `name` is for humans and for an engine's hierarchy. */
  readonly role: string;
  readonly parent: string | null;
  readonly kind: "root" | "joint" | "endSite";
  /** Parent-local metres. Under the identity rest pose this is worldRest(child) - worldRest(parent). */
  readonly offset: Vec3;
  readonly restPosition: Vec3;
  readonly axes: readonly JointAxis[];
  /** Sphere radius for the viewer; 1.1x the widest cylinder the joint joins. */
  readonly radius: number | null;
  readonly color: "left" | "right" | "center";
  readonly effector?: string;
}

export interface RigBone {
  readonly name: string;
  readonly from: string;
  readonly to: string;
  readonly radius: number;
  readonly length: number;
  /** Lowest surface point of the capsule at rest. Penetration is measured against THIS, not Y=0. */
  readonly clearanceAtRest: number;
  readonly sinksBelowFloor: boolean;
}

export interface RigMarker {
  readonly name: string;
  readonly role: string;
  readonly parent: string;
  readonly offset: Vec3;
  readonly restPosition: Vec3;
  readonly contact: true;
}

export interface IkChain {
  readonly name: string;
  readonly effector: string;
  readonly tip: string;
  readonly root: string;
  readonly mid: string;
  readonly pole: Vec3;
  readonly poleNote?: string;
}

export interface HumanoidRig {
  readonly id: string;
  readonly version: number;
  readonly schema: string;
  readonly conventions: Record<string, string> & {
    readonly dofOrder: readonly AxisName[];
    readonly unit: "m";
    readonly upAxis: "+Y";
    readonly forwardAxis: "+Z";
    readonly leftAxis: "+X";
  };
  readonly root: { readonly joint: string; readonly restPosition: Vec3; readonly note?: string };
  readonly bindHeight: number;
  readonly stats: Record<string, unknown>;
  readonly proportions: Record<string, unknown>;
  readonly mesh: Record<string, unknown>;
  readonly joints: readonly RigJoint[];
  readonly bones: readonly RigBone[];
  readonly markers: readonly RigMarker[];
  readonly effectors: readonly { name: string; tip: string; root: string; mid: string }[];
  readonly ikChains: readonly IkChain[];
  readonly restPose: {
    readonly joints: Record<string, Vec3>;
    readonly markers: Record<string, Vec3>;
  };
}
